import{_ as a,c as t,o as r,aj as s}from"./chunks/framework.CDhdelVI.js";const f=JSON.parse('{"title":"Salt","description":"","frontmatter":{"title":"Salt"},"headers":[],"relativePath":"ingredients/salt.md","filePath":"ingredients/salt.md"}'),l={name:"ingredients/salt.md"};function n(o,e,i,h,d,g){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="salt" tabindex="-1">Salt <a class="header-anchor" href="#salt" aria-label="Permalink to “Salt”">​</a></h1><p>Salt is the traffic cop in dough: it keeps yeast from speeding, tightens the gluten net, and makes wheat actually taste like wheat.</p><h2 id="typical-baker-s-percentage" tabindex="-1">Typical Baker&#39;s Percentage <a class="header-anchor" href="#typical-baker-s-percentage" aria-label="Permalink to “Typical Baker&#39;s Percentage”">​</a></h2><p>Around <strong>2%</strong> is the working sweet spot: enough control, enough flavor, not enough to choke fermentation.</p><p>Most bread doughs use <strong>2% salt</strong>, which is:</p><ul><li>Enough for flavor</li><li>Helps tighten gluten</li><li>Controls fermentation speed</li><li>Standard across most professional formulas</li></ul><hr><h2 id="how-salt-affects-dough" tabindex="-1">How Salt Affects Dough <a class="header-anchor" href="#how-salt-affects-dough" aria-label="Permalink to “How Salt Affects Dough”">​</a></h2><h3 id="strengthens-gluten" tabindex="-1"><strong>Strengthens Gluten</strong> <a class="header-anchor" href="#strengthens-gluten" aria-label="Permalink to “Strengthens Gluten”">​</a></h3><p>Salt tightens protein bonds, helping dough hold shape.</p><h3 id="slows-fermentation" tabindex="-1"><strong>Slows Fermentation</strong> <a class="header-anchor" href="#slows-fermentation" aria-label="Permalink to “Slows Fermentation”">​</a></h3><p>Higher salt concentration inhibits yeast activity.</p><ul><li>At <strong>2%</strong> - Normal</li><li>Above <strong>2.3-2.5%</strong> - Noticeably slower rise</li><li>At <strong>3%+</strong> - Yeast may struggle</li></ul><h3 id="improves-flavor" tabindex="-1"><strong>Improves Flavor</strong> <a class="header-anchor" href="#improves-flavor" aria-label="Permalink to “Improves Flavor”">​</a></h3><p>Salt balances wheat flavor and prevents bland dough.</p><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>Don&#39;t let salt touch yeast directly when mixing - mix into flour first.</li><li>Measure salt by <strong>weight</strong>, not volume. A teaspoon of fine salt and a teaspoon of kosher salt are not equivalent in grams.</li><li>If dough is rising too fast, increase salt by <strong>0.2-0.3%</strong>.</li><li>For low-salt diets, reduce to <strong>1.5%</strong>, but expect faster fermentation.</li><li>In hot kitchens or very warm dough, a small bump (<strong>+0.1% to +0.3%</strong>) can help keep fermentation under control.</li><li>Use non-iodized fine sea salt or kosher salt for cleaner, more consistent flavor.</li><li>If dough feels wild, salt is your brake pedal; if dough feels asleep, don&#39;t press harder.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li><li><a href="/ingredients/yeast.html">Yeast</a></li><li><a href="/recipes/french-bread.html">French Bread</a></li></ul>',20)])])}const p=a(l,[["render",n]]);export{f as __pageData,p as default};
